export async function execute(args = {}) {
  const rows = args.rows || []
  if (!rows.length) return { text: '' }
  const cols = Object.keys(rows[0])
  const line = (r) => '| ' + cols.map((c) => r[c] ?? '').join(' | ') + ' |'
  const text = [line(Object.fromEntries(cols.map((c) => [c, c]))), '| ' + cols.map(() => '---').join(' | ') + ' |', ...rows.map(line)].join('\n')
  return { text }
}

import test from 'node:test'
import assert from 'node:assert'
import { execute } from '../lib/impl.js'
test('table', async () => {
  const r = await execute({ rows: [{ a: 1, b: 2 }] })
  assert.match(r.text, /\| a \| b \|/)
})
